node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
const root='~/forge-evidence/pi-atdd/plt-82-evaluator-verdicts';
const ids=['r-4d5cd9','r-6c0d14','r-3581b3','r-3790dc','r-16090e','r-3c1b09','r-86b4ee'];
const ranking=JSON.parse(await readFile(`${root}/batch-2/ranking.json`));
assert.deepEqual(ranking.ranking.map(x=>x.id).sort(),[...ids].sort());
let previous;
for(const entry of ranking.ranking){
 const path=`${root}/${['r-4d5cd9','r-6c0d14'].includes(entry.id)?'batch-2/':''}${entry.id}/verdict.json`;
 const v=JSON.parse(await readFile(path)); const criteria=Object.values(v.rubric);
 assert.equal(criteria.length,10); assert(criteria.every(c=>Number.isInteger(c.score)&&c.score>=0&&c.score<=3&&c.why));
 const total=criteria.reduce((s,c)=>s+c.score,0); const functional=criteria.slice(0,7).reduce((s,c)=>s+c.score,0);
 assert.equal(v.overall,total); assert.equal(entry.overall,total);
 const tuple=[v.hiddenTests.countedPass,functional,total,criteria[7].score,criteria[8].score];
 if(previous){const i=tuple.findIndex((x,i)=>x!==previous[i]); assert(i<0 || previous[i]>tuple[i]);}
 previous=tuple;
 console.log(`${entry.rank}\t${entry.id}\t${v.hiddenTests.countedPass}/16\t${functional}/21\t${total}/30`);
}
assert(ranking.notes.join(' ').includes('built in two batches'));
console.log('Validated: seven ids, all rubric sums, ranking order, and two-batch provenance.');
